/bin/bash -c "python3 - <<'PY'
def eta(a,b):
 if b<a: return 1-b/a
 if b>a: return 1-(1-b)/(1-a)
 return 0.
def dcp_binary(ps,ws):
 vals=[(sum(w*eta(a,p) for w,p in zip(ws,ps)),a) for a in [0.,1.,*ps]]
 return min(vals)
print('Robustness check: two equally weighted groups, one conditional row')
for delta in (.1,.01,.001):
 d,b=dcp_binary([.5,.5+delta],[.5,.5])
 print({'delta':delta,'joint_total_variation':delta/2,'DCP':d,'minimizing_baseline':b})
print('Clipping check')
print('Original:',dcp_binary([0.,1.],[.5,.5]))
eps=1e-5
print('Clipped:',dcp_binary([eps,1-eps],[.5,.5]))
def surrogate(a,b):
 return a*(a-b) if b<a else (1-a)*(b-a)
x=(.4,.1); y=(.6,.5); midpoint=tuple((a+b)/2 for a,b in zip(x,y))
print('Eq.18 convexity check:',{'x':x,'y':y,'f_midpoint':surrogate(*midpoint),'average_endpoint_values':(surrogate(*x)+surrogate(*y))/2})
PY"
